```python
import math

L1 = 0.5            # 根元〜肘 [m]
L2 = 0.4            # 肘〜先端 [m]
LINK_HALF_WIDTH = 0.02   # リンク太さ 4cm の半分
SAFETY_MARGIN = 0.02     # 安全余裕 2cm
JOINT_LIMIT = 2.98       # 可動範囲 ±2.98 rad
TOLERANCE = 0.01         # 最終誤差の許容値 1cm（IK誤差はこれよりはるかに小さい）
SAMPLE_MARGIN = 0.005    # [追加] 補間サンプリングの離散化誤差ぶんの追加余裕
EDGE_STEP = 0.005        # [追加] 経路干渉チェックの関節角刻み [rad]
GRID_STEP = 0.1          # [追加] 関節空間グリッド探索の刻み [rad]


def _wrap(a):
    """角度を (-pi, pi] に正規化する。"""
    while a > math.pi:
        a -= 2.0 * math.pi
    while a <= -math.pi:
        a += 2.0 * math.pi
    return a


def _fk(q1, q2):
    """順運動学: 肘と先端の座標を返す。"""
    ex = L1 * math.cos(q1)
    ey = L1 * math.sin(q1)
    tx = ex + L2 * math.cos(q1 + q2)
    ty = ey + L2 * math.sin(q1 + q2)
    return (ex, ey), (tx, ty)


def _seg_point_dist(p, a, b):
    """線分 ab と点 p の最短距離。"""
    abx, aby = b[0] - a[0], b[1] - a[1]
    apx, apy = p[0] - a[0], p[1] - a[1]
    len2 = abx * abx + aby * aby
    t = 0.0 if len2 == 0 else max(0.0, min(1.0, (apx * abx + apy * aby) / len2))
    cx, cy = a[0] + t * abx, a[1] + t * aby
    return math.hypot(p[0] - cx, p[1] - cy)


def _pose_collides(q1, q2, obstacles):
    """ある姿勢で、いずれかのリンクが障害物（+太さ+余裕）に接触するか。"""
    elbow, tip = _fk(q1, q2)
    base = (0.0, 0.0)
    for ob in obstacles:
        c = (ob["x"], ob["y"])
        clearance = ob["r"] + LINK_HALF_WIDTH + SAFETY_MARGIN + SAMPLE_MARGIN
        if _seg_point_dist(c, base, elbow) < clearance:
            return True
        if _seg_point_dist(c, elbow, tip) < clearance:
            return True
    return False


def _path_collides(q_start, q_end, obstacles, max_step=EDGE_STEP):
    """関節空間の直線補間経路を細かくサンプリングして干渉を調べる。
    [変更] 分割数を関節移動量に応じて決める（長い移動でも刻みが粗くならない）。"""
    d = max(abs(q_end[0] - q_start[0]), abs(q_end[1] - q_start[1]))
    steps = max(1, int(math.ceil(d / max_step)))
    for i in range(steps + 1):
        s = i / steps
        q1 = q_start[0] + s * (q_end[0] - q_start[0])
        q2 = q_start[1] + s * (q_end[1] - q_start[1])
        if _pose_collides(q1, q2, obstacles):
            return True
    return False


def _plan_via_grid(start, goals, obstacles):
    """[追加] 直線で行けない場合の迂回経路探索。
    関節空間をグリッド化して BFS し、ゴールへ直線で繋がる点を選んで
    最後に近道（ショートカット）で経由点を減らす。"""
    n = int(JOINT_LIMIT / GRID_STEP)
    free_cache = {}

    def node_q(node):
        return (node[0] * GRID_STEP, node[1] * GRID_STEP)

    def node_free(node):
        if node not in free_cache:
            q = node_q(node)
            free_cache[node] = not _pose_collides(q[0], q[1], obstacles)
        return free_cache[node]

    s_node = (0, 0)
    if not node_free(s_node):
        return None

    # BFS（8近傍）。エッジも干渉チェックする
    parent = {s_node: None}
    hops = {s_node: 0}
    queue = [s_node]
    head = 0
    while head < len(queue):
        cur = queue[head]
        head += 1
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if di == 0 and dj == 0:
                    continue
                nb = (cur[0] + di, cur[1] + dj)
                if abs(nb[0]) > n or abs(nb[1]) > n or nb in parent:
                    continue
                if not node_free(nb):
                    continue
                if _path_collides(node_q(cur), node_q(nb), obstacles):
                    continue
                parent[nb] = cur
                hops[nb] = hops[cur] + 1
                queue.append(nb)

    # 各ゴール候補について、直線で繋げられる最良の到達済みノードを探す
