    N = 30
    step = LIM / N
    R = 0.3  # ゴールと接続する半径 [rad]

    def qof(key):
        if isinstance(key[0], str):
            return goals[key[1]]
        return ((key[0] - N) * step, (key[1] - N) * step)

    def neighbors(key):
        if isinstance(key[0], str):
            gq = goals[key[1]]
            ci, cj = int(round(gq[0] / step)) + N, int(round(gq[1] / step)) + N
            m = int(R / step) + 1
            out = []
            for i in range(ci - m, ci + m + 1):
